void addCel(State& s,const std::string& layer,const std::string& frame,Pixel pixel,int height=1,int x=0,int y=0){Cel c;c.id=layer+":"+frame;c.layerId=layer;c.frameId=frame;c.surface=Surface{1,height,x,y,{},{},moon::timeline::LinkedPixelStorage(std::vector<Pixel>(height,pixel))};s.cels.push_back(std::move(c));}
State pair(){State s;s.layers={{"child",U"child"},{"base",U"base"}};s.layers[0].groupId="g";s.groups={group("g")};s.frames={{"a",100}};addCel(s,"child","a",green);addCel(s,"base","a",red);return s;}
Pixel render(const State& s){return compositeNormalRegion(Timeline(s),"a",{0,0,1,1})[0];}
